(1121, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Di dalam sebuah kotak terdapat 5 kelereng merah dan 3 kelereng biru. Budi mengambil satu kelereng secara acak dan ternyata berwarna merah. Jika kelereng tersebut tidak dikembalikan ke dalam kotak, berapakah peluang Budi mengambil kelereng merah lagi pada pengambilan kedua?', NULL, TRUE),
(1122, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Andi dan Budi bermain lempar dua buah dadu. Aturannya: Andi menang jika jumlah mata dadu genap, dan Budi menang jika jumlah mata dadu ganjil. Berdasarkan aturan tersebut, kesimpulan yang paling tepat adalah...', NULL, TRUE),
(1123, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Siska melempar sekeping koin sebanyak 5 kali, dan kelima lemparan tersebut menghasilkan sisi "Angka". Siska berkesimpulan bahwa pada lemparan ke-6, sisi "Gambar" pasti akan muncul untuk menyeimbangkan hasil. Evaluasi dari kesimpulan Siska adalah...', NULL, TRUE),
(1124, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah kantong berisi 4 bola merah dan 6 bola putih. Berapa banyak bola merah yang harus ditambahkan ke dalam kantong agar peluang terambilnya bola merah berubah menjadi 1/2?', NULL, TRUE),
(1125, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Terdapat sebuah roda putar (spinner) yang terbagi menjadi beberapa juring berukuran sama: 3 juring warna Merah, 2 juring warna Kuning, dan 1 juring warna Biru. Jika panitia ingin membuat peluang berhentinya jarum di warna Kuning menjadi 1/2 tanpa menambah ukuran roda, apa yang harus dilakukan?', NULL, TRUE),
(1126, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Doni lupa 1 digit terakhir dari password HP-nya (angka 0-9). Ia hanya ingat bahwa angka tersebut adalah bilangan ganjil yang lebih besar dari 3. Berapakah peluang Doni berhasil menebak password tersebut pada percobaan pertama?', NULL, TRUE),
(1127, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Dalam sebuah keranjang, peluang terambilnya buah apel yang busuk adalah 0,05. Jika total buah apel di dalam keranjang tersebut adalah 80 buah, berapa banyak buah apel yang kondisinya masih bagus?', NULL, TRUE),
(1128, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Tiga orang siswa membandingkan peluang mereka dalam permainan yang berbeda. Ali melempar 1 dadu dan menang jika muncul angka 6. Beni melempar 2 koin dan menang jika muncul keduanya Angka. Cita mengambil 1 kartu dari set bridge dan menang jika muncul kartu As. Urutan siswa dari yang memiliki peluang menang terbesar hingga terkecil adalah...', NULL, TRUE),
(1129, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah kantong berisi kelereng berwarna merah, kuning, dan hijau. Peluang terambilnya kelereng merah adalah 1/3, dan peluang kuning adalah 1/4. Jika diketahui jumlah kelereng hijau adalah 10 buah, maka berapakah total seluruh kelereng di dalam kantong tersebut?', NULL, TRUE),
(1130, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Pada permainan papan, seseorang harus membayar Rp5.000 untuk memutar spinner yang terbagi menjadi 8 juring sama besar (1 juring bertanda "Bintang" dan 7 juring "Kosong"). Jika menunjuk "Bintang", ia mendapat hadiah Rp24.000. Jika permainan ini dimainkan berulang-ulang dalam jangka panjang, analisislah keuntungan/kerugian dari pihak pemain!', NULL, TRUE),
(1131, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Sebuah papan target berbentuk lingkaran dengan jari-jari 14 cm. Di tengahnya terdapat lingkaran Bullseyeberwarna merah dengan jari-jari 7 cm. Jika sebuah anak panah pasti menancap secara acak di papan target tersebut, berapakah peluang panah menancap tepat di Bullseye?', NULL, TRUE),
(1132, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Pada sebuah tes pilihan ganda yang berisi 10 pertanyaan, setiap pertanyaan memiliki 4 pilihan jawaban (A, B, C, D). Jika Dina menjawab semua soal sepenuhnya dengan cara menebak acak, kesimpulan mana yang paling masuk akal mengenai frekuensi harapan jawaban benar Dina?', NULL, TRUE),
(1133, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Peneliti ingin memprediksi populasi ikan di sebuah danau. Mereka menangkap 50 ikan, memberinya tanda (tag), lalu melepaskannya kembali. Seminggu kemudian, mereka menjaring 40 ikan secara acak, dan menemukan ada 4 ikan yang memiliki tanda. Berapakah perkiraan populasi total ikan di danau tersebut berdasarkan penalaran rasio peluang?', NULL, TRUE),
(1134, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Dari sebuah kotak yang berisi angka 1 sampai 5, diambil 2 angka secara sekaligus. Jika diketahui hasil penjumlahan kedua angka tersebut adalah bilangan genap, berapakah peluang bahwa kedua angka yang diambil tersebut adalah ganjil?', NULL, TRUE),
(1135, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'SINGLE_CHOICE', 'Untuk membuat suatu permainan dadu menjadi tidak adil (menguntungkan pihak penebak angka ganjil), seseorang merekayasa dadu tersebut dengan memberikan beban tambahan. Jika sekarang peluang munculnya mata dadu ganjil adalah dua kali lipat dari mata dadu genap, berapakah peluang munculnya angka 2?', NULL, TRUE),
(1136, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah kotak A berisi 2 bola merah dan 3 bola putih. Kotak B berisi 4 bola merah dan 1 bola putih. Evaluasilah mana strategi penarikan kesimpulan yang BENAR jika kita ingin mendapatkan 1 bola merah! (Pilih lebih dari satu)', NULL, TRUE),
(1137, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Dari sebuah eksperimen melempar dadu bersisi 6 sebanyak 600 kali, didapatkan data empirik munculnya mata dadu "1" sebanyak 110 kali. Manakah penalaran yang logis terkait situasi ini? (Pilih lebih dari satu)', NULL, TRUE),
(1138, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Tiga keping uang logam dilempar secara bersamaan. Jika diketahui bahwa minimal ada satu sisi Gambar (G) yang muncul, manakah pernyataan berikut yang bernilai BENAR? (Pilih lebih dari satu)', NULL, TRUE),
(1139, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Sebuah kotak awalnya berisi 2 kelereng Merah dan 2 kelereng Hitam. Riko mengambil satu kelereng (Kelereng Pertama), lalu tanpa mengembalikannya, ia mengambil kelereng kedua. Analisislah perubahan probabilitas yang terjadi dan pilih pernyataan yang BENAR! (Pilih lebih dari satu)', NULL, TRUE),
(1140, 1, 10, 3, NULL, 'LEVEL_EXERCISE', 'COMPLEX_CHOICE', 'Guru memberikan tantangan: "Buatlah desain sebuah kantong kelereng sekecil mungkin (jumlah kelereng paling sedikit) yang memenuhi syarat: Peluang Merah = 1/2, Peluang Biru = 1/3, dan sisanya kelereng Kuning". Manakah dari pernyataan di bawah ini yang merupakan generalisasi matematis yang TEPAT dari desain tersebut? (Pilih lebih dari satu)', NULL, TRUE)
